import { cloneElement, isValidElement, type ReactElement, type ReactNode } from "react";

export const locales = ["nl", "de", "en"] as const;
export type Locale = (typeof locales)[number];

export const localePrefix: Record<Locale, string> = { nl: "", de: "/de", en: "/en" };

export function localizedPath(locale: Locale, path: string) {
  if (!path.startsWith("/") || path.startsWith("//")) return path;
  const normalized = path === "/" ? "" : `/${path.replace(/^\/+|\/+$/g, "")}`;
  return `${localePrefix[locale]}${normalized || "/"}`;
}

export function languageAlternates(path: string) {
  return {
    nl: `https://goodtimescoverband.nl${localizedPath("nl", path)}`,
    de: `https://goodtimescoverband.nl${localizedPath("de", path)}`,
    en: `https://goodtimescoverband.nl${localizedPath("en", path)}`,
    "x-default": `https://goodtimescoverband.nl${localizedPath("nl", path)}`,
  };
}

