const dictionaries: Record<Exclude<Locale, "nl">, Record<string, string>> = { de, en };

export function translate(locale: Locale, value: string) {
  if (locale === "nl") return value;
  const trimmed = value.trim();
  const translated = dictionaries[locale][trimmed];
  if (!translated) return value;
  return `${value.slice(0, value.length - value.trimStart().length)}${translated}${value.slice(value.trimEnd().length)}`;
}

const translatableProps = new Set(["alt", "aria-label", "placeholder", "title"]);

export function localizeNode(locale: Locale, node: ReactNode): ReactNode {
  if (locale === "nl" || node == null || typeof node === "boolean") return node;
  if (typeof node === "string") return translate(locale, node);
  if (typeof node === "number") return node;
  if (Array.isArray(node)) return node.map((child) => localizeNode(locale, child));
  if (!isValidElement(node)) return node;
  const element = node as ReactElement<Record<string, unknown>>;
  const props: Record<string, unknown> = { ...element.props };
  for (const key of translatableProps) if (typeof props[key] === "string") props[key] = translate(locale, props[key] as string);
  if ("children" in props) props.children = localizeNode(locale, props.children as ReactNode);
  return cloneElement(element, props);
}
